 "content": "def transform(grid):
    """Replace any solid monochrome rectangle of at least 5x5 with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # For each color, a summed-area table makes exact monochrome tests cheap.
    for color in set(v for row in grid for v in row):
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            row_sum = 0
            for c in range(w):
                row_sum += (grid[r][c] == color)
                pref[r + 1][c + 1] = pref[r][c + 1] + row_sum
        for r0 in range(h - 4):
            for r1 in range(r0 + 4, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 4):
                    for c1 in range(c0 + 4, w):
                        area = rh * (c1 - c0 + 1)
                        count = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                                 - pref[r1 + 1][c0] + pref[r0][c0])
                        if count == area:
                            for r in range(r0, r1 + 1):
                                for c in range(c0, c1 + 1):
                                    out[r][c] = 4
    return out
